def check_equation(a, p):
    # a is the sequence (list)
    # p is the index
    if p < 0:
        return "p must be non-negative"

    try:
        # Calculate a_{a_p}
        idx1 = a[p]
        if idx1 >= len(a):
            return "Index out of bounds for a_p"

        a_a_p = a[idx1]

        # Calculate a_{a_{a_p}}
        idx2 = a_a_p
        if idx2 >= len(a):
            return "Index out of bounds for a_{a_p}"

        lhs = a[idx2]

        # Calculate a_{p+1} + 1
        if p+1 >= len(a):
            return "Index out of bounds for a_{p+1}"

        rhs = a[p+1] + 1

        return lhs == rhs
    except IndexError as e:
        return f"IndexError during calculation: {e}"

# Test the derived solution a_p = p+1
# We need at least a_0 through a_5 for p=3 check
A_linear = [i + 1 for i in range(6)] 
print("Testing a_p = p+1 for p=0, 1, 2, 3:")
for p in range(4):
    result = check_equation(A_linear, p)
    print(f"p={p}: {result}")

# Test the contradictory case a_0=0 (checking p=0)
A_zero_start = [0, 0, 0, 0] # Initial guess for structure
print("\nTesting a_0 = 0 (A=[0, 0, 0, 0] for illustration):")
try:
